from pathlib import Path
import csv,json
R=Path(__file__).resolve().parents[1]
def read(p):return list(csv.DictReader((R/p).open()))
def matrix(rows):return [list(rows[0])]+[list(r.values()) for r in rows] if rows else [['Status'],['No eligible records']]
primary=read('evidence/primary_studies.csv');registry=read('logs/article_registry.csv');quality=read('evidence/evidence_quality.csv');counts=json.loads((R/'logs/selection_counts.json').read_text())
gaps=[dict(Observation='Validation nesting insufficiently explicit in several included studies',Study_IDs='P002;P003;P005;P006',Counterexample='P004 external ADNI/TADPOLE tests; P013/P017 explicit train/test splits',Strength='Scoped descriptive audit, not field-wide prevalence',Future_Work='Re-evaluate with ranking/search within nested training folds',Evidence='Evidence_Quality and per-study page notes'),dict(Observation='Efficiency definitions differ substantially',Study_IDs='P002;P003;P004;P006;P010;P023',Counterexample='P010 clearly defines selection-only time',Strength='Direct full-text comparison',Future_Work='Report preprocessing, search, final training, prediction, hardware and unique fits',Evidence='P002 pp9-10;P003 p12;P004 p11/supplement;P006 p14;P010 p20'),dict(Observation='Metric labels can conceal distinct targets',Study_IDs='P004',Counterexample='P003 explicitly defines macro classification F1',Strength='Direct definition, no prevalence claim',Future_Work='Separate feature-recovery and class-prediction scores',Evidence='P004 PDF p10,Tables4/9;P003 pp8-10'),dict(Observation='General review originality not established',Study_IDs='S01;S02;S03',Counterexample='S01 has own benchmark and code table',Strength='High overlap risk',Future_Work='Expand survey audit and primary corpus before journal novelty claim',Evidence='notes/03_survey_overlap_audit.md')]
summary=[['GA feature selection evidence map','Value'],['Included primary studies',counts['included_primary']],['Pending full-text primary candidates',counts['pending_primary']],['Excluded unrelated candidate',counts['excluded_primary']],['Secondary reviews (not primary)',3],['Search date','2026-10-09'],['Corpus limit','Selected structured review; search not exhaustive'],['Publication originality','NOT ESTABLISHED'],['External similarity score','NOT TESTED']]
readme=[['Field','Definition'],['Scope','GA-central supervised classification feature selection,2020-2026-10-09'],['Status',f"{counts['included_primary']} included primaries; {counts['pending_primary']} pending and {counts['excluded_primary']} excluded by documented relevance decisions"],['Evidence levels','FULL_TEXT, ABSTRACT_ONLY, METADATA_ONLY; previews do not establish full methods/results'],['Missing fields','NOT REPORTED means inspected source lacks field; NOT VERIFIED means unavailable or unextracted; N/A inapplicable'],['Quality coding','Yes explicit; No explicit contrary design; Unclear ambiguous; Not reported absent after text inspection'],['AI authorship','All generated prose is reference material; university forbids AI-authored final writing'],['Citation policy','Stable Study_ID plus physical PDF page/table; secondary reviews excluded from primary count'],['Sources','Canonical CSV/evidence notes accompany workbook; DOI/publisher URLs clickable'],['Numeric units','Reported_Results values numeric; metric units and conditions separate'],['Modification date','2026-10-09']]
tabs={'Summary':summary,'Primary_Studies':matrix([x for x in primary if x['Verification_Status']!='EXCLUDED']),'Secondary_Reviews':matrix([x for x in registry if x['kind']=='review']),'Search_Log':matrix(read('logs/search_queries.csv')),'Screening':matrix(read('logs/search_and_screening.csv')),'Method_Taxonomy':matrix([{k:r[k] for k in ['Study_ID','GA_Variant_or_Hybrid','Chromosome_Encoding','Fitness_Objectives','Classifier_and_Baselines','Evidence_Page_Table_Figure']} for r in primary if r['Included (Y/N)']=='Y']),'Evidence_Quality':matrix(quality),'Reported_Results':matrix(read('evidence/reported_results.csv')),'Research_Gaps':matrix(gaps),'PDF_Requests':matrix(read('logs/pdf_requests.csv')),'Excluded_Papers':matrix([x for x in primary if x['Verification_Status']=='EXCLUDED']),'READ_ME':readme,'Expanded_Results':matrix(read('Results_and_Graphs/major_revision/summary_tidy.csv')),'Expanded_Stability':matrix(read('Results_and_Graphs/major_revision/stability.csv'))}
for name,rows in tabs.items():
    for row in rows[1:]:
        for i,v in enumerate(row):
            if rows[0][i] in ['Year','year','Value','number','mean','sd','n','pairs','pairwise_jaccard_mean'] and str(v).replace('.','',1).isdigit():row[i]=float(v) if '.' in str(v) else int(v)
(R/'tmp/matrix_data.json').write_text(json.dumps(tabs,indent=2));print('Prepared',len(tabs),'tabs')
